export function getOfficialGisDistrict(districtId: string, districtName?: string): OfficialGisDistrictData {
  const normId = (districtId || '').toLowerCase().replace(/[^a-z0-9]/g, '').replace('the', '');
  const normName = (districtName || '').toLowerCase().replace(/[^a-z0-9]/g, '').replace('the', '');

  // Exact key match
  if (OFFICIAL_TAMIL_NADU_GIS[normId]) {
    return OFFICIAL_TAMIL_NADU_GIS[normId];
  }

  // Partial match by name or key
  for (const [key, data] of Object.entries(OFFICIAL_TAMIL_NADU_GIS)) {
    if (key === normId || key === normName || data.districtName.toLowerCase().includes(normName) || normName.includes(key)) {
      return data;
    }
  }

  // Fallback to Erode or first district
  return OFFICIAL_TAMIL_NADU_GIS['erode'] || Object.values(OFFICIAL_TAMIL_NADU_GIS)[0];
}
